(7694542, 1261335, 4008, '<td valign="top">I can see from the shadow it is against the light but it does not make much use of the effect.</td>', 'I can see from the shadow it is against the light but it does not make much use of the effect.', '2021-05-19 11:57:03.000000', NULL, 1),
(7694543, 1261580, 4008, '<td valign="top">Yes, the backlight adds a nice translucent effect to the wing but the overall impact of the contre-jour on the image is low because there is also a lot of light from other directions. Beautiful but in this challenge not very strong imho</td>', 'Yes, the backlight adds a nice translucent effect to the wing but the overall impact of the contre-jour on the image is low because there is also a lot of light from other directions. Beautiful but in this challenge not very strong imho', '2021-05-19 12:00:59.000000', NULL, 1),
(7694552, 1261527, 96751, '<td valign="top">Spectacular, but not really "contre jour"</td>', 'Spectacular, but not really "contre jour"', '2021-05-19 12:09:38.000000', NULL, 1),
(7694554, 1261567, 96751, '<td valign="top">Love this image, but technically this is a shadow, not contre-jour.</td>', 'Love this image, but technically this is a shadow, not contre-jour.', '2021-05-19 12:11:22.000000', NULL, 1),
(7694560, 1261606, 4008, '<td valign="top">Great portrait expressing strong love. Beautiful soft backlit atmosphere.</td>', 'Great portrait expressing strong love. Beautiful soft backlit atmosphere.', '2021-05-19 12:20:09.000000', NULL, 1),
(7694561, 1261619, 4008, '<td valign="top">Love the fact it is not just a silhouette, but you can see the structure and color.</td>', 'Love the fact it is not just a silhouette, but you can see the structure and color.', '2021-05-19 12:21:17.000000', NULL, 1),
