(7694697, 1261618, 4008, '<td valign="top">Great colours and I like it how the sun shines through the flowers.</td>', 'Great colours and I like it how the sun shines through the flowers.', '2021-05-21 16:20:11.000000', NULL, 1),
(7694698, 1261581, 4008, '<td valign="top">Easy on the saturation please...Beautiful scene and evening light nevertheless.</td>', 'Easy on the saturation please...Beautiful scene and evening light nevertheless.', '2021-05-21 16:20:36.000000', NULL, 1),
(7694701, 1261362, 4008, '<td valign="top">Great sky and the dog is positioned just perfectly.</td>', 'Great sky and the dog is positioned just perfectly.', '2021-05-21 16:24:29.000000', NULL, 1),
(7694702, 1261295, 4008, '<td valign="top">A bit better than most other simple silhouettes against a sunset. This one has some depth and shows nice detail in the splashing water.</td>', 'A bit better than most other simple silhouettes against a sunset. This one has some depth and shows nice detail in the splashing water.', '2021-05-21 16:25:40.000000', NULL, 1),
(7694703, 1261615, 4008, '<td valign="top">Just another silhouette to me, with special effects. Cutout? No depth. Could be a Hallmark postcard.</td>', 'Just another silhouette to me, with special effects. Cutout? No depth. Could be a Hallmark postcard.', '2021-05-21 16:27:08.000000', NULL, 1),
(7694704, 1261614, 4008, '<td valign="top">The light behind her serves as a nice background but does not affect your subject much. She is lit from the front. Therefore not very strong in this challenge imho.</td>', 'The light behind her serves as a nice background but does not affect your subject much. She is lit from the front. Therefore not very strong in this challenge imho.', '2021-05-21 16:27:49.000000', NULL, 1),
