(7694859, 1261421, 143116, '<td valign="top">Textbook contre-jour with shadows falling towards the viewer, and diverging at the edges of the frame. And Namibia is and remains a fascinating country!</td>', 'Textbook contre-jour with shadows falling towards the viewer, and diverging at the edges of the frame. And Namibia is and remains a fascinating country!', '2021-05-23 10:49:28.000000', NULL, 1),
(7694860, 1261571, 143116, '<td valign="top">Beautiful composition overall, with the contrast against the reflecting light, well chosen height of the drone, and a mirror image lighthouse.</td>', 'Beautiful composition overall, with the contrast against the reflecting light, well chosen height of the drone, and a mirror image lighthouse.', '2021-05-23 10:51:43.000000', NULL, 1),
(7694861, 1261514, 143116, '<td valign="top">I like the viewpoint and the starburst from the sun. The in-camera / in-lens reflections are a bit of a dsitraction.</td>', 'I like the viewpoint and the starburst from the sun. The in-camera / in-lens reflections are a bit of a dsitraction.', '2021-05-23 10:53:57.000000', NULL, 1),
(7694862, 1261606, 143116, '<td valign="top">The love radiates, supported by the subtle color palette.</td>', 'The love radiates, supported by the subtle color palette.', '2021-05-23 10:54:34.000000', NULL, 1),
(7694878, 1261563, 114285, '<td valign="top">The fuzzy hair on the mans arms ;)<br/> <br/>Since this has a dog in it it will probably win, Dpc loves dogs.</td>', 'The fuzzy hair on the mans arms ;) Since this has a dog in it it will probably win, Dpc loves dogs.', '2021-05-23 22:09:50.000000', NULL, 1),
(7694879, 1261601, 114285, '<td valign="top">Great image. I nearly entered a very similar one.</td>', 'Great image. I nearly entered a very similar one.', '2021-05-23 22:10:12.000000', NULL, 1),
(7694880, 1261610, 114285, '<td valign="top">I really want to like this one more, but I feel  you probably shouldve cloned out the lens flare. It doesnt add anything to the image. Lovely moment caught though.</td>', 'I really want to like this one more, but I feel  you probably shouldve cloned out the lens flare. It doesnt add anything to the image. Lovely moment caught though.', '2021-05-23 22:11:47.000000', NULL, 1),
(7694896, 1261295, 3306, '<td valign="top">My favorite of the challenge. I really like the overall mood of your composition. The sun shining through the splashing water and the action of the moment are outstanding. The birds are a plus. The exposure and shutter speed are perfect.</td>', 'My favorite of the challenge. I really like the overall mood of your composition. The sun shining through the splashing water and the action of the moment are outstanding. The birds are a plus. The exposure and shutter speed are perfect.', '2021-05-24 07:34:48.000000', NULL, 1),
(7694897, 1261343, 3306, '<td valign="top">I really like how the light illuminates the cactus flower. Great detail. I was so impressed by the flower I didnt see the bees until I read your title! Nice addition to an already excellent shot.</td>', 'I really like how the light illuminates the cactus flower. Great detail. I was so impressed by the flower I didnt see the bees until I read your title! Nice addition to an already excellent shot.', '2021-05-24 07:37:29.000000', NULL, 1),
(7694898, 1261421, 3306, '<td valign="top">One of my favorites. Great capture of the sun rays in the perfect place. The silhouettes of the trees and shadows is outstanding. Such a desolate feeling.</td>', 'One of my favorites. Great capture of the sun rays in the perfect place. The silhouettes of the trees and shadows is outstanding. Such a desolate feeling.', '2021-05-24 07:40:12.000000', NULL, 1),
(7694899, 1261571, 3306, '<td valign="top">Very cool shot. I like everything about it. The shadow of the tower accentuates the lighthouse and draws the eye to the subject and purpose of the composition. My choice to ribbon.</td>', 'Very cool shot. I like everything about it. The shadow of the tower accentuates the lighthouse and draws the eye to the subject and purpose of the composition. My choice to ribbon.', '2021-05-24 07:44:58.000000', NULL, 1),
(7694900, 1261581, 3306, '<td valign="top">Very interesting use of the lens utilizing the curved aberration to accentuate the beauty of the scene. I really enjoy looking at your composition. Its a wonderful scene!</td>', 'Very interesting use of the lens utilizing the curved aberration to accentuate the beauty of the scene. I really enjoy looking at your composition. Its a wonderful scene!', '2021-05-24 07:48:46.000000', NULL, 1),
